# Inspect child node.
if node_ent.is_dir():
	# If the entry is a directory, recurse into it.
	try:
		yield from _iter_tree_next(node_ent.path, node_rel, memo, on_error)
	except RecursionError as e:
		# A symlink loop was detected.
		warnings.warn(f'recursed on "{e.real_path}" ("{e.first_path}" and "{e.second_path}")', RuntimeWarning)
	except OSError as e:
		if on_error is not None:
			on_error(e)
else:
	yield node_rel
